package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type TempRec struct { // 01 TEMP-REC, 8 bytes
	TcSensor string // PIC X(4) @0 len=4
	TcF decimal.Decimal // PIC 9(3)V9 @4 len=4
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N" // PIC X len=1 = "N"
var WsC decimal.Decimal = decimal.NewFromInt(0) // PIC S9(3)V99 len=5 = 0
var WsFreeze int64 = 0 // PIC 99 len=2 = 0
var WsCount int64 = 0 // PIC 99 len=2 = 0
var WsFEd string // PIC ZZ9.9 len=5
var WsCEd string // PIC -ZZ9.99 len=7

var curRec TempRec
var inputLines []string
var inputIdx int

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func padRight(s string, n int) string {
	if len(s) >= n {
		return s[:n]
	}
	return s + strings.Repeat(" ", n-len(s))
}

func parseTcF(field string) decimal.Decimal {
	// field length 4, digits only, implied 1 decimal
	// spaces treated as zeros
	if len(field) < 4 {
		field = field + strings.Repeat(" ", 4-len(field))
	} else if len(field) > 4 {
		field = field[:4]
	}
	var v int64 = 0
	for i := 0; i < len(field); i++ {
		c := field[i]
		var d int64
		if c >= '0' && c <= '9' {
			d = int64(c - '0')
		} else {
			d = 0
		}
		v = v*10 + d
	}
	return decimal.New(v, -1)
}

func formatZZ9_9(v decimal.Decimal) string {
	// PIC ZZ9.9 width 5
	// truncate toward zero to 1 decimal
	t := v.Truncate(1)
	neg := t.IsNegative()
	if neg {
		t = t.Neg()
	}
	// scaled integer = t*10
	scaled := t.Shift(1).IntPart() // >=0
	// keep low-order 4 digits (3 int + 1 frac) ? high-order drop
	// integer part low 3 digits, frac 1 digit
	// total scaled mod 10000
	scaled = scaled % 10000
	intPart := scaled / 10
	fracPart := scaled % 10
	intStr := fmt.Sprintf("%03d", intPart)
	place := []byte{'Z', 'Z', '9'}
	outInt := make([]byte, 3)
	// suppression
	for i := 0; i < 3; i++ {
		d := intStr[i]
		if place[i] == '9' {
			outInt[i] = d
		} else {
			if d == '0' {
				// check if any non-zero to the left (in intStr)
				allZeroLeft := true
				for j := i + 1; j < 3; j++ {
					// need to know if any significant digit to right?
					// Z suppression: leading zeros become spaces
					_ = j
				}
				// determine if all digits from i to end are zero? No, leading zero suppression:
				// space if all digits from start through i are zero and there is a non-suppressed digit later
				// Simpler: if all digits 0..i are '0' and (there exists non-zero after i or i<2 with 9 at end ensures at least last prints)
				// Actually for ZZ9, zeros at 0,1 become spaces unless a more significant? They are most significant, so:
				isLeading := true
				for k := 0; k <= i; k++ {
					if intStr[k] != '0' {
						isLeading = false
						break
					}
				}
				// also if the whole number is zero, last 9 still prints 0, Z's become spaces
				if isLeading {
					// if this is last position and placeholder Z? but last is 9 so not here
					outInt[i] = ' '
				} else {
					outInt[i] = d
				}
				_ = allZeroLeft
			} else {
				outInt[i] = d
			}
		}
	}
	// Need to handle case where a Z position has non-zero: subsequent Z zeros should print 0
	// Above logic fails for e.g. 101? intStr "101": i=0 d='1' -> prints '1'; i=1 d='0', isLeading checks 0..1 contains '1' => not leading => prints '0'. Good.
	// For "010": i=0 '0' leading => ' '; i=1 '1' -> prints '1'. Good.
	fracCh := byte('0' + fracPart)
	_ = neg // F temps non-negative; ignore sign (COBOL would show absolute? but values >=0)
	return string(outInt) + "." + string([]byte{fracCh})
}

func formatMinusZZ9_99(v decimal.Decimal) string {
	// PIC -ZZ9.99 width 7 : fixed leading sign + ZZ9.99
	t := v.Truncate(2)
	neg := t.Sign() < 0
	abs := t
	if neg {
		abs = t.Neg()
	}
	scaled := abs.Shift(2).IntPart()
	scaled = scaled % 100000 // low-order 3 int + 2 frac = 5 digits
	intPart := scaled / 100
	fracPart := scaled % 100
	intStr := fmt.Sprintf("%03d", intPart)
	outInt := make([]byte, 3)
	place := []byte{'Z', 'Z', '9'}
	for i := 0; i < 3; i++ {
		d := intStr[i]
		if place[i] == '9' {
			outInt[i] = d
		} else {
			if d == '0' {
				isLeading := true
				for k := 0; k <= i; k++ {
					if intStr[k] != '0' {
						isLeading = false
						break
					}
				}
				if isLeading {
					outInt[i] = ' '
				} else {
					outInt[i] = d
				}
			} else {
				outInt[i] = d
			}
		}
	}
	sign := byte(' ')
	if neg {
		sign = '-'
	}
	fracStr := fmt.Sprintf("%02d", fracPart)
	return string([]byte{sign}) + string(outInt) + "." + fracStr
}

func computeWsC(f decimal.Decimal) decimal.Decimal {
	// C = (F - 32) * 5 / 9 rounded to 2 decimals, stored in S9(3)V99 with low-order truncation
	// Exact integer arithmetic: Tf = F*10 integer
	tf := f.Shift(1).IntPart()
	num := (tf - 320) * 50 // (Tf-320)*50 / 9 = C*100
	den := int64(9)
	q := num / den // trunc toward zero (Go)
	r := num % den
	absR := r
	if absR < 0 {
		absR = -absR
	}
	// round half away from zero: if 2*|r| >= den (den odd so > equivalent, but include = for completeness)
	if absR*2 >= den {
		if num >= 0 {
			q++
		} else {
			q--
		}
	}
	// store truncation to S9(3)V99: keep low-order 3 int digits => R mod 100000
	qr := q % 100000
	return decimal.New(qr, -2)
}

func READPARA() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	if len(line) < 8 {
		line = line + strings.Repeat(" ", 8-len(line))
	} else if len(line) > 8 {
		line = line[:8]
	}
	sensor := line[0:4]
	ff := line[4:8]
	curRec.TcSensor = sensor
	curRec.TcF = parseTcF(ff)
}

func PROCESSPARA() {
	WsC = computeWsC(curRec.TcF)
	if WsC.Sign() < 0 {
		WsFreeze = (WsFreeze + 1) % 100
	}
	WsCount = (WsCount + 1) % 100
	WsFEd = formatZZ9_9(curRec.TcF)
	WsCEd = formatMinusZZ9_99(WsC)
	fmt.Println(curRec.TcSensor+" "+WsFEd+"F "+WsCEd+"C")
	READPARA()
}

func MAINPARA() {
	READPARA()
	for !isInputDone() {
		PROCESSPARA()
	}
	cntStr := fmt.Sprintf("%02d", WsCount)
	frzStr := fmt.Sprintf("%02d", WsFreeze)
	fmt.Println("READINGS: "+cntStr+" BELOW ZERO: "+frzStr)
}

func main() {
	f, err := os.Open("input.dat")
	if err != nil {
		// empty input if file missing? COBOL OPEN INPUT would fail; treat as empty?
		// To match expected behaviour, report error
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	sc := bufio.NewScanner(f)
	// allow long lines
	sc.Buffer(make([]byte, 0, 64*1024), 1024*1024)
	for sc.Scan() {
		line := sc.Text()
		// Scanner strips trailing \r for \r\n; ensure no extra stripping
		inputLines = append(inputLines, line)
	}
	f.Close()
	if err := sc.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	_ = padRight
	MAINPARA()
}
